function journalAction(a){
 if(a==='insights')insightsDialog();
 else if(a==='entry-preferences')preferencesDialog();
 else if(a==='filters')filtersDialog();
 else if(a==='reset-filters'){search='';filter='all';expenseFilters={payer:'',category:'',from:'',to:'',sort:'newest'};render();}
 else if(a==='export-filtered')exportCSV(filteredExpenses());
 else if(a==='settlement-summary')settlementSummary();
 else return false;
 return true;
}
function repeatExpense(id){const e=data.expenses.find(x=>x.id===id);if(!e)return toast('Expense no longer exists.');expenseForm(null,{...repeatPreset(e),repeat:true});}
function preferenceKey(){return `together-entry:${data.id}:${data.seat}`;}
function entryPreferences(){
 try{const p=JSON.parse((demo?sessionStorage:localStorage).getItem(preferenceKey())||'{}');return {category:catalogValues(data,'categories').includes(p.category)?p.category:'Groceries',split:['half','a','b'].includes(p.split)?p.split:'half',visibility:p.visibility==='private'?'private':'shared'};}catch{return {};}
}
function preferencesDialog(){
 const p=entryPreferences();modal('Make adding quicker',`<p class="small muted">Choose how a new expense starts. You can change these on each entry. Saved for your household on this device.</p><form id="preferences-form"><label class="field"><span>Default category</span><select name="category">${catalogValues(data,'categories').map(c=>`<option value="${esc(c)}" ${c===p.category?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="field"><span>Default visibility</span><select name="visibility"><option value="shared" ${p.visibility!=='private'?'selected':''}>Whole household</option><option value="private" ${p.visibility==='private'?'selected':''}>My couple only</option></select></label><label class="field"><span>Default split for shared expenses</span><select name="split">${splitOptions(p.split||'half')}</select></label><p class="small muted">The payer starts as you. Repeating an expense uses that expense’s details.</p><p class="error" role="alert"></p><button class="primary full">Save preferences</button></form>`);
 $('#preferences-form').onsubmit=e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));try{(demo?sessionStorage:localStorage).setItem(preferenceKey(),JSON.stringify(p));sheet.close();toast('Entry preferences saved');}catch{errorIn(e.target,'This browser could not save preferences. Please allow site storage.');}};
}
function filtersDialog(){
 const f=expenseFilters,categories=[...new Set(scope().map(e=>e.category))].sort((a,b)=>a.localeCompare(b));
 modal('Find an expense',`<form id="filter-form"><label class="field"><span>Paid by</span><select name="payer"><option value="">Everyone</option>${data.names.map((n,i)=>`<option value="${i}" ${f.payer===String(i)?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label class="field"><span>Category</span><select name="category"><option value="">All categories</option>${categories.map(c=>`<option value="${esc(c)}" ${f.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><div class="two"><label class="field"><span>From · optional</span><input type="date" name="from" value="${f.from}"></label><label class="field"><span>To · optional</span><input type="date" name="to" value="${f.to}"></label></div><p class="error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" id="clear-filters">Clear</button><button class="primary">Show expenses</button></div></form>`);
 $('#clear-filters').onclick=()=>{journalAction('reset-filters');sheet.close();};$('#filter-form').onsubmit=e=>{e.preventDefault();const next=Object.fromEntries(new FormData(e.target));if(next.from&&next.to&&next.from>next.to)return errorIn(e.target,'Choose an end date on or after the start.');expenseFilters={...expenseFilters,...next};sheet.close();render();};
}
function insightsDialog(){
 const items=insightPeriod==='sheet'?scope():insightPeriod==='month'?data.expenses.filter(e=>e.date.slice(0,7)===today().slice(0,7)):data.expenses;
 const stats=summarizeSpending(items),label=insightPeriod==='sheet'?currentName():insightPeriod==='month'?new Date().toLocaleDateString('en-AU',{month:'long',year:'numeric'}):'All your sheets';
 modal('Spending insights',`<div class="switches insight-periods">${[['sheet','This sheet'],['month','This month'],['all','All time']].map(([id,t])=>`<button data-insight-period="${id}" class="${insightPeriod===id?'selected':''}" aria-pressed="${insightPeriod===id}">${t}</button>`).join('')}</div><p class="small muted insight-context">${esc(label)} · expenses visible to you</p><div class="insight-hero"><span>Total spending</span><strong>${money(stats.total)}</strong><div><span>${stats.count} expenses</span><span>${money(stats.average)} average</span></div></div><div class="insight-split"><div><small>Shared</small><strong>${money(stats.shared)}</strong></div><div><small>Couple only</small><strong>${money(stats.privateTotal)}</strong></div></div>${stats.count?`<div class="section-head"><h3>By category</h3><span class="small muted">Share of total</span></div><div class="glass spending-panel">${stats.categories.map(([c,n])=>`<div class="budget-row"><div class="between small"><span>${esc(c)}</span><strong>${money(n)}</strong></div><div class="bar" role="img" aria-label="${esc(c)}: ${Math.round(n/stats.total*100)} percent of spending"><i style="width:${n/stats.total*100}%"></i></div></div>`).join('')}</div><div class="section-head"><h3>Who paid</h3></div><div class="glass payer-list">${stats.people.map((n,i)=>`<div class="payer-line"><span class="avatar ${group(i)==='b'?'b':''}">${esc(initials(data.names[i]))}</span><span>${esc(data.names[i])}</span><strong>${money(n)}</strong></div>`).join('')}</div>`:'<div class="empty"><p>Add expenses to see where your money goes.</p></div>'}<p class="small muted">Includes settled expenses. These are spending totals, not amounts owed.</p><button class="secondary full" id="export-insights">${icon('receipt')} Export these expenses</button>`);
 sheet.querySelectorAll('[data-insight-period]').forEach(b=>b.onclick=()=>{insightPeriod=b.dataset.insightPeriod;insightsDialog();});$('#export-insights').onclick=()=>exportCSV(items);
}
function settlementSummary(){
 const items=scope().filter(e=>e.visibility==='shared'&&!e.settlement),b=balance(items),text=`Together · ${currentName()}\n${b.net?`${couple(b.net>0?'b':'a')} owes ${money(b.amount)} to ${couple(b.net>0?'a':'b')}.`:'Both couples are balanced.'}\n${items.length} unsettled shared expenses\n${couple('a')} paid ${money(b.aPaid)}\n${couple('b')} paid ${money(b.bPaid)}\nAs of ${new Date().toLocaleDateString('en-AU')}. Please check Together for the latest balance.\nThis is a summary, not a payment confirmation.`;
 modal('Settlement summary',`<p class="small muted">A ready-to-copy note for your household. Couple-only expenses and access links are excluded.</p><textarea id="settlement-text" readonly rows="9" aria-label="Settlement summary">${esc(text)}</textarea><button id="copy-summary" class="primary full" style="margin-top:14px">${icon('copy')} Copy summary</button><p class="small muted" id="copy-status" role="status"></p>`);
 $('#copy-summary').onclick=async()=>{try{await navigator.clipboard.writeText(text);$('#copy-status').textContent='Copied. Paste it into your household chat.';}catch{$('#settlement-text').select();$('#copy-status').textContent='Select and copy the summary above.';}};
}
